// Differential checks of MapFilter-pbo.js against Lean, generated by leanscript --check
import * as M from "./MapFilter-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1([])", () => M.test1([]), "#[]", false);
check("test1([]) twice", () => ((a0) => (M.test1(a0), M.test1(a0)))([]), "#[]", false);
check("test1([0])", () => M.test1([0]), "#[]", false);
check("test1([0]) twice", () => ((a0) => (M.test1(a0), M.test1(a0)))([0]), "#[]", false);
check("test1([0, 1, 2])", () => M.test1([0, 1, 2]), "#[]", false);
check("test1([0, 1, 2]) twice", () => ((a0) => (M.test1(a0), M.test1(a0)))([0, 1, 2]), "#[]", false);
check("test1([13, 5, 2, 1])", () => M.test1([13, 5, 2, 1]), "#[26, 10]", false);
check("test1([13, 5, 2, 1]) twice", () => ((a0) => (M.test1(a0), M.test1(a0)))([13, 5, 2, 1]), "#[26, 10]", false);
check("test3([])", () => M.test3([]), "{#[], #[]}", false);
check("test3([]) twice", () => ((a0) => (M.test3(a0), M.test3(a0)))([]), "{#[], #[]}", false);
check("test3([0])", () => M.test3([0]), "{#[0], #[]}", false);
check("test3([0]) twice", () => ((a0) => (M.test3(a0), M.test3(a0)))([0]), "{#[0], #[]}", false);
check("test3([0, 1, 2])", () => M.test3([0, 1, 2]), "{#[0, 2, 4], #[]}", false);
check("test3([0, 1, 2]) twice", () => ((a0) => (M.test3(a0), M.test3(a0)))([0, 1, 2]), "{#[0, 2, 4], #[]}", false);
check("test3([13, 5, 2, 1])", () => M.test3([13, 5, 2, 1]), "{#[26, 10, 4, 2], #[26, 10]}", false);
check("test3([13, 5, 2, 1]) twice", () => ((a0) => (M.test3(a0), M.test3(a0)))([13, 5, 2, 1]), "{#[26, 10, 4, 2], #[26, 10]}", false);
check("test4([])", () => M.test4([]), "#[]", false);
check("test4([]) twice", () => ((a0) => (M.test4(a0), M.test4(a0)))([]), "#[]", false);
check("test4([0])", () => M.test4([0]), "#[1]", false);
check("test4([0]) twice", () => ((a0) => (M.test4(a0), M.test4(a0)))([0]), "#[1]", false);
check("test4([0, 1, 2])", () => M.test4([0, 1, 2]), "#[1, 2, 3]", false);
check("test4([0, 1, 2]) twice", () => ((a0) => (M.test4(a0), M.test4(a0)))([0, 1, 2]), "#[1, 2, 3]", false);
check("test4([13, 5, 2, 1])", () => M.test4([13, 5, 2, 1]), "#[14, 6, 3, 2]", false);
check("test4([13, 5, 2, 1]) twice", () => ((a0) => (M.test4(a0), M.test4(a0)))([13, 5, 2, 1]), "#[14, 6, 3, 2]", false);
check("test5([])", () => M.test5([]), "#[]", false);
check("test5([]) twice", () => ((a0) => (M.test5(a0), M.test5(a0)))([]), "#[]", false);
check("test5([0])", () => M.test5([0]), "#[]", false);
check("test5([0]) twice", () => ((a0) => (M.test5(a0), M.test5(a0)))([0]), "#[]", false);
check("test5([0, 1, 2])", () => M.test5([0, 1, 2]), "#[]", false);
check("test5([0, 1, 2]) twice", () => ((a0) => (M.test5(a0), M.test5(a0)))([0, 1, 2]), "#[]", false);
check("test5([13, 5, 2, 1])", () => M.test5([13, 5, 2, 1]), "#[13, 5]", false);
check("test5([13, 5, 2, 1]) twice", () => ((a0) => (M.test5(a0), M.test5(a0)))([13, 5, 2, 1]), "#[13, 5]", false);

console.log(`MapFilter-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
